-- TRAVIO initial schema (Cloudflare D1 / SQLite)
-- Traveler references without ON DELETE use NO ACTION semantics: a traveler
-- with expenses cannot be removed, but deleting a whole trip cascades cleanly.
-- Conventions:
--   * IDs are random UUIDs generated by the application (never sequential)
--   * Timestamps are ISO-8601 UTC strings
--   * Calendar dates are 'YYYY-MM-DD', times 'HH:MM' (local time of the place)
--   * Money is stored as INTEGER minor units; exchange rates as decimal TEXT
--   * Every collaborative resource carries trip_id for authorization scoping
--   * `version` is incremented on every content change (optimistic locking)

CREATE TABLE users (
  id                 TEXT PRIMARY KEY,
  email              TEXT NOT NULL UNIQUE COLLATE NOCASE,
  display_name       TEXT NOT NULL,
  password_hash      TEXT NOT NULL,
  locale             TEXT NOT NULL DEFAULT 'de',
  is_instance_admin  INTEGER NOT NULL DEFAULT 0 CHECK (is_instance_admin IN (0, 1)),
  created_at         TEXT NOT NULL,
  updated_at         TEXT NOT NULL
);

-- Session IDs are SHA-256 hashes of the random cookie token; the raw token is
-- never stored.
CREATE TABLE sessions (
  id            TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at    TEXT NOT NULL,
  expires_at    TEXT NOT NULL,
  last_seen_at  TEXT NOT NULL
);
CREATE INDEX idx_sessions_user ON sessions(user_id);
CREATE INDEX idx_sessions_expires ON sessions(expires_at);

-- Fixed-window counters for abuse protection (login, setup, invitations).
CREATE TABLE rate_limits (
  key           TEXT PRIMARY KEY,
  window_start  INTEGER NOT NULL,
  count         INTEGER NOT NULL
);

CREATE TABLE trips (
  id                   TEXT PRIMARY KEY,
  name                 TEXT NOT NULL,
  destination_country  TEXT,
  start_date           TEXT NOT NULL,
  end_date             TEXT NOT NULL,
  cover_image_url      TEXT,
  base_currency        TEXT NOT NULL,
  local_currency       TEXT,
  description          TEXT,
  status               TEXT NOT NULL DEFAULT 'planning' CHECK (status IN ('planning', 'confirmed', 'completed')),
  archived_at          TEXT,
  origin_name          TEXT,
  origin_lat           REAL,
  origin_lng           REAL,
  home_timezone        TEXT NOT NULL DEFAULT 'Europe/Berlin',
  import_key           TEXT,
  is_demo              INTEGER NOT NULL DEFAULT 0 CHECK (is_demo IN (0, 1)),
  created_by           TEXT REFERENCES users(id) ON DELETE SET NULL,
  version              INTEGER NOT NULL DEFAULT 1,
  created_at           TEXT NOT NULL,
  updated_at           TEXT NOT NULL,
  CHECK (end_date >= start_date)
);
-- An import (e.g. "thailand-2026") can exist only once per user.
CREATE UNIQUE INDEX idx_trips_import_key ON trips(created_by, import_key) WHERE import_key IS NOT NULL;

CREATE TABLE trip_members (
  trip_id     TEXT NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role        TEXT NOT NULL CHECK (role IN ('owner', 'editor', 'viewer')),
  created_at  TEXT NOT NULL,
  PRIMARY KEY (trip_id, user_id)
);
CREATE INDEX idx_trip_members_user ON trip_members(user_id);

-- Travelers are the people of a trip (used for expenses). They may or may not
-- have a user account.
CREATE TABLE travelers (
  id          TEXT PRIMARY KEY,
  trip_id     TEXT NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
  name        TEXT NOT NULL,
  user_id     TEXT REFERENCES users(id) ON DELETE SET NULL,
  color       TEXT NOT NULL,
  sort_order  INTEGER NOT NULL DEFAULT 0,
  version     INTEGER NOT NULL DEFAULT 1,
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL
);
CREATE INDEX idx_travelers_trip ON travelers(trip_id);
CREATE UNIQUE INDEX idx_travelers_trip_user ON travelers(trip_id, user_id) WHERE user_id IS NOT NULL;

CREATE TABLE invitations (
  id           TEXT PRIMARY KEY,
  trip_id      TEXT NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
  token_hash   TEXT NOT NULL UNIQUE,
  role         TEXT NOT NULL CHECK (role IN ('owner', 'editor', 'viewer')),
  traveler_id  TEXT REFERENCES travelers(id) ON DELETE SET NULL,
  email        TEXT,
  created_by   TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at   TEXT NOT NULL,
  expires_at   TEXT NOT NULL,
  used_at      TEXT,
  used_by      TEXT REFERENCES users(id) ON DELETE SET NULL
);
CREATE INDEX idx_invitations_trip ON invitations(trip_id);

CREATE TABLE destinations (
  id                     TEXT PRIMARY KEY,
  trip_id                TEXT NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
  name                   TEXT NOT NULL,
  country                TEXT,
  arrival_date           TEXT NOT NULL,
  departure_date         TEXT NOT NULL,
  timezone               TEXT NOT NULL,
  accommodation_name     TEXT,
  accommodation_address  TEXT,
  accommodation_notes    TEXT,
  lat                    REAL,
  lng                    REAL,
  notes                  TEXT,
  cover_image_url        TEXT,
  sort_order             INTEGER NOT NULL DEFAULT 0,
  version                INTEGER NOT NULL DEFAULT 1,
  created_at             TEXT NOT NULL,
  updated_at             TEXT NOT NULL,
  CHECK (departure_date >= arrival_date)
);
CREATE INDEX idx_destinations_trip ON destinations(trip_id, sort_order);

CREATE TABLE saved_places (
  id              TEXT PRIMARY KEY,
  trip_id         TEXT NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
  name            TEXT NOT NULL,
  category        TEXT NOT NULL,
  description     TEXT,
  address         TEXT,
  lat             REAL,
  lng             REAL,
  external_url    TEXT,
  notes           TEXT,
  favorite        INTEGER NOT NULL DEFAULT 0 CHECK (favorite IN (0, 1)),
  destination_id  TEXT REFERENCES destinations(id) ON DELETE SET NULL,
  created_by      TEXT REFERENCES users(id) ON DELETE SET NULL,
  version         INTEGER NOT NULL DEFAULT 1,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);
CREATE INDEX idx_places_trip ON saved_places(trip_id);

CREATE TABLE activities (
  id              TEXT PRIMARY KEY,
  trip_id         TEXT NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
  title           TEXT NOT NULL,
  description     TEXT,
  category        TEXT NOT NULL,
  date            TEXT NOT NULL,
  start_time      TEXT,
  end_time        TEXT,
  location_name   TEXT,
  lat             REAL,
  lng             REAL,
  est_cost_minor  INTEGER CHECK (est_cost_minor IS NULL OR est_cost_minor >= 0),
  currency        TEXT,
  booking_status  TEXT NOT NULL DEFAULT 'planned' CHECK (booking_status IN ('planned', 'unconfirmed', 'booked', 'cancelled')),
  completed       INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
  notes           TEXT,
  place_id        TEXT REFERENCES saved_places(id) ON DELETE SET NULL,
  sort_order      INTEGER NOT NULL DEFAULT 0,
  created_by      TEXT REFERENCES users(id) ON DELETE SET NULL,
  updated_by      TEXT REFERENCES users(id) ON DELETE SET NULL,
  version         INTEGER NOT NULL DEFAULT 1,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);
CREATE INDEX idx_activities_trip_date ON activities(trip_id, date, sort_order);

CREATE TABLE bookings (
  id                    TEXT PRIMARY KEY,
  trip_id               TEXT NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
  title                 TEXT NOT NULL,
  type                  TEXT NOT NULL CHECK (type IN ('flight', 'hotel', 'ferry', 'train', 'bus', 'car', 'activity', 'other')),
  provider              TEXT,
  reference             TEXT,
  start_date            TEXT,
  start_time            TEXT,
  start_timezone        TEXT,
  end_date              TEXT,
  end_time              TEXT,
  end_timezone          TEXT,
  from_location         TEXT,
  to_location           TEXT,
  location              TEXT,
  -- Destination this booking belongs to (e.g. the hotel of a stop)
  destination_id        TEXT REFERENCES destinations(id) ON DELETE SET NULL,
  -- Transport legs: NULL on one side means the trip origin / home
  from_destination_id   TEXT REFERENCES destinations(id) ON DELETE SET NULL,
  to_destination_id     TEXT REFERENCES destinations(id) ON DELETE SET NULL,
  -- Costs: amount kind, booking status and payment status are independent
  price_minor           INTEGER CHECK (price_minor IS NULL OR price_minor >= 0),
  currency              TEXT,
  persons_count         INTEGER CHECK (persons_count IS NULL OR persons_count > 0),
  unit_price_minor      INTEGER CHECK (unit_price_minor IS NULL OR unit_price_minor >= 0),
  unit_price_note       TEXT,
  cost_kind             TEXT NOT NULL DEFAULT 'actual' CHECK (cost_kind IN ('actual', 'estimate', 'budget_cap')),
  booking_status        TEXT NOT NULL DEFAULT 'planned' CHECK (booking_status IN ('planned', 'unconfirmed', 'booked', 'cancelled')),
  payment_status        TEXT NOT NULL DEFAULT 'unknown' CHECK (payment_status IN ('unknown', 'unpaid', 'partial', 'paid')),
  paid_by_traveler_id   TEXT REFERENCES travelers(id) ON DELETE SET NULL,
  clarification_note    TEXT,
  notes                 TEXT,
  -- Reserved for confirmation documents in a private R2 bucket
  document_key          TEXT,
  import_ref            TEXT,
  created_by            TEXT REFERENCES users(id) ON DELETE SET NULL,
  version               INTEGER NOT NULL DEFAULT 1,
  created_at            TEXT NOT NULL,
  updated_at            TEXT NOT NULL,
  CHECK ((price_minor IS NULL AND unit_price_minor IS NULL) OR currency IS NOT NULL)
);
CREATE INDEX idx_bookings_trip_start ON bookings(trip_id, start_date, start_time);

CREATE TABLE expenses (
  id                   TEXT PRIMARY KEY,
  trip_id              TEXT NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
  title                TEXT NOT NULL,
  amount_minor         INTEGER NOT NULL CHECK (amount_minor > 0),
  currency             TEXT NOT NULL,
  date                 TEXT NOT NULL,
  category             TEXT NOT NULL CHECK (category IN ('accommodation', 'food', 'transportation', 'activities', 'shopping', 'other')),
  paid_by_traveler_id  TEXT NOT NULL REFERENCES travelers(id),
  split_method         TEXT NOT NULL CHECK (split_method IN ('equal', 'exact', 'percent')),
  -- Historical conversion: never recalculated when rates change later
  fx_rate              TEXT NOT NULL,
  fx_source            TEXT NOT NULL CHECK (fx_source IN ('identity', 'manual', 'cached', 'provider')),
  fx_date              TEXT,
  base_amount_minor    INTEGER NOT NULL CHECK (base_amount_minor >= 0),
  notes                TEXT,
  -- A booking can be transferred into the wallet at most once
  booking_id           TEXT UNIQUE REFERENCES bookings(id) ON DELETE SET NULL,
  created_by           TEXT REFERENCES users(id) ON DELETE SET NULL,
  version              INTEGER NOT NULL DEFAULT 1,
  created_at           TEXT NOT NULL,
  updated_at           TEXT NOT NULL
);
CREATE INDEX idx_expenses_trip_date ON expenses(trip_id, date);

CREATE TABLE expense_splits (
  expense_id        TEXT NOT NULL REFERENCES expenses(id) ON DELETE CASCADE,
  traveler_id       TEXT NOT NULL REFERENCES travelers(id),
  share_minor       INTEGER NOT NULL CHECK (share_minor >= 0),
  base_share_minor  INTEGER NOT NULL CHECK (base_share_minor >= 0),
  weight            INTEGER,
  PRIMARY KEY (expense_id, traveler_id)
);
CREATE INDEX idx_expense_splits_traveler ON expense_splits(traveler_id);

-- Repayments between travelers (kept strictly separate from expenses)
CREATE TABLE settlements (
  id                 TEXT PRIMARY KEY,
  trip_id            TEXT NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
  from_traveler_id   TEXT NOT NULL REFERENCES travelers(id),
  to_traveler_id     TEXT NOT NULL REFERENCES travelers(id),
  amount_minor       INTEGER NOT NULL CHECK (amount_minor > 0),
  currency           TEXT NOT NULL,
  fx_rate            TEXT NOT NULL,
  fx_source          TEXT NOT NULL CHECK (fx_source IN ('identity', 'manual', 'cached', 'provider')),
  fx_date            TEXT,
  base_amount_minor  INTEGER NOT NULL CHECK (base_amount_minor >= 0),
  date               TEXT NOT NULL,
  notes              TEXT,
  created_by         TEXT REFERENCES users(id) ON DELETE SET NULL,
  version            INTEGER NOT NULL DEFAULT 1,
  created_at         TEXT NOT NULL,
  updated_at         TEXT NOT NULL,
  CHECK (from_traveler_id <> to_traveler_id)
);
CREATE INDEX idx_settlements_trip ON settlements(trip_id, date);

-- Stored exchange rates of a trip ("1 currency = rate base_currency")
CREATE TABLE exchange_rates (
  id              TEXT PRIMARY KEY,
  trip_id         TEXT NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
  currency        TEXT NOT NULL,
  base_currency   TEXT NOT NULL,
  rate            TEXT NOT NULL,
  source          TEXT NOT NULL CHECK (source IN ('manual', 'provider')),
  effective_date  TEXT NOT NULL,
  created_by      TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at      TEXT NOT NULL
);
CREATE INDEX idx_exchange_rates_trip ON exchange_rates(trip_id, currency, effective_date);

-- Packing lists: trip-bound (shared or private) or personal templates (trip_id NULL)
CREATE TABLE packing_lists (
  id             TEXT PRIMARY KEY,
  trip_id        TEXT REFERENCES trips(id) ON DELETE CASCADE,
  owner_user_id  TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  visibility     TEXT NOT NULL CHECK (visibility IN ('shared', 'private')),
  is_template    INTEGER NOT NULL DEFAULT 0 CHECK (is_template IN (0, 1)),
  name           TEXT NOT NULL,
  version        INTEGER NOT NULL DEFAULT 1,
  created_at     TEXT NOT NULL,
  updated_at     TEXT NOT NULL,
  CHECK ((is_template = 1 AND trip_id IS NULL) OR (is_template = 0 AND trip_id IS NOT NULL))
);
CREATE INDEX idx_packing_lists_trip ON packing_lists(trip_id);
CREATE INDEX idx_packing_lists_owner ON packing_lists(owner_user_id);

CREATE TABLE packing_items (
  id          TEXT PRIMARY KEY,
  list_id     TEXT NOT NULL REFERENCES packing_lists(id) ON DELETE CASCADE,
  name        TEXT NOT NULL,
  category    TEXT NOT NULL CHECK (category IN ('clothing', 'electronics', 'toiletries', 'documents', 'medication', 'other')),
  quantity    INTEGER NOT NULL DEFAULT 1 CHECK (quantity >= 1),
  packed      INTEGER NOT NULL DEFAULT 0 CHECK (packed IN (0, 1)),
  sort_order  INTEGER NOT NULL DEFAULT 0,
  version     INTEGER NOT NULL DEFAULT 1,
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL
);
CREATE INDEX idx_packing_items_list ON packing_items(list_id, sort_order);

-- Idempotency log for offline sync operations
CREATE TABLE sync_operations (
  op_id        TEXT PRIMARY KEY,
  user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  trip_id      TEXT NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
  entity       TEXT NOT NULL,
  action       TEXT NOT NULL,
  entity_id    TEXT NOT NULL,
  status       TEXT NOT NULL CHECK (status IN ('applied', 'conflict', 'rejected')),
  result_json  TEXT,
  created_at   TEXT NOT NULL
);
CREATE INDEX idx_sync_operations_created ON sync_operations(created_at);

-- Minimal audit trail for financially relevant and destructive changes
CREATE TABLE audit_log (
  id          TEXT PRIMARY KEY,
  trip_id     TEXT REFERENCES trips(id) ON DELETE CASCADE,
  user_id     TEXT REFERENCES users(id) ON DELETE SET NULL,
  entity      TEXT NOT NULL,
  entity_id   TEXT NOT NULL,
  action      TEXT NOT NULL,
  summary     TEXT,
  created_at  TEXT NOT NULL
);
CREATE INDEX idx_audit_log_trip ON audit_log(trip_id, created_at);
